mapper.select:
SELECT o.customer_id dimension,SUM((SELECT COUNT(*) FROM return_order x WHERE x.order_id=o.id)) return_count,SUM((SELECT COUNT(*) FROM return_order x WHERE x.order_id=o.id AND x.status='REFUNDED')) refunded_returns,SUM(o.total_amount) order_value
FROM sales_order o WHERE o.ordered_at>=#{from} AND o.ordered_at<#{until}
GROUP BY o.customer_id ORDER BY return_count DESC LIMIT 50

SELECT o.customer_id dimension,SUM((SELECT COUNT(*) FROM sales_order_item x WHERE x.order_id=o.id)) item_lines,SUM((SELECT COUNT(DISTINCT x.sku_id) FROM sales_order_item x WHERE x.order_id=o.id)) distinct_sku_touches,SUM(o.total_amount) order_value
FROM sales_order o WHERE o.ordered_at>=#{from} AND o.ordered_at<#{until}
GROUP BY o.customer_id ORDER BY item_lines DESC LIMIT 50

SELECT o.warehouse_id dimension,SUM((SELECT COUNT(*) FROM shipment x WHERE x.order_id=o.id)) shipment_count,SUM((SELECT COUNT(*) FROM shipment x WHERE x.order_id=o.id AND x.status='DELIVERED')) delivered_shipments,SUM(o.total_amount) order_value
FROM sales_order o WHERE o.ordered_at>=#{from} AND o.ordered_at<#{until}
GROUP BY o.warehouse_id ORDER BY shipment_count DESC LIMIT 50

SELECT o.channel dimension,SUM((SELECT COUNT(*) FROM payment x WHERE x.order_id=o.id AND x.status='SUCCESS')) payment_records,SUM((SELECT COUNT(*) FROM payment x WHERE x.order_id=o.id AND x.status='REFUNDED')) refunded_payment_records,SUM(o.total_amount) order_value
FROM sales_order o WHERE o.ordered_at>=#{from} AND o.ordered_at<#{until}
GROUP BY o.channel ORDER BY payment_records DESC LIMIT 50
